    ('GBP', '1.27', '2026-10-01', 'Indicative reference rate (demo default)'),
    ('INR', '0.012', '2026-10-01', 'Indicative reference rate (demo default)'),
    ('AED', '0.2723', '2026-10-01', 'Indicative reference rate (demo default)'),
    ('SGD', '0.74', '2026-10-01', 'Indicative reference rate (demo default)'),
    ('AUD', '0.66', '2026-10-01', 'Indicative reference rate (demo default)'),
    ('CAD', '0.73', '2026-10-01', 'Indicative reference rate (demo default)'),
